pub struct StorageEngine {
    memtable: Arc<RwLock<SkipList<Vec<u8>, Vec<u8>>>>,
    wal_writer: Mutex<WalWriter>,
    block_cache: LruCache<BlockId, BlockData>,
}

impl StorageEngine {
    pub fn put(&self, key: &[u8], val: &[u8]) -> Result<()> {
        // 1. 预写日志保障崩溃一致性
        self.wal_writer.lock().append(key, val)?;
        // 2. 写入内存跳表索引
        self.memtable.write().insert(key.to_vec(), val.to_vec());
        Ok(())
    }
}
